// Initializes a level's seed and dispatches generation based on eDrlgType (maze / preset / outdoor). Always runs InitRelated and initializes warp coordinates after generation.
void __stdcall InitLevel(D2DrlgLevelStrc * pLevel) {
    Seed::InitSeed_Param_666(&pLevel->sSeed, pLevel->pDrlg->dwStartSeed + pLevel->eD2LevelId);
    int drlgType = pLevel->eDrlgType;
    switch (drlgType) {
      case 1:
        {
          Maze::DRLGMAZE_GenerateLevel(pLevel);
          break;
        }
      case 2:
        {
          Preset::DRLGPRESET_InitializeRoomEx(pLevel);
          DRLG_ApplyRoomExStateFlags(pLevel);
          DRLGWARP_InitLevelWarpCoordinates(pLevel);
          return;
        }
      case 3:
        {
          Outdoors::DRLGOUTDOOR_GenerateLevel(pLevel);
          DRLG_ApplyRoomExStateFlags(pLevel);
          DRLGWARP_InitLevelWarpCoordinates(pLevel);
          return;
        }
    }

    DRLG_ApplyRoomExStateFlags(pLevel);
    DRLGWARP_InitLevelWarpCoordinates(pLevel);
}

// Gets the bounding rectangle (min/max X/Y) of all rooms in a level by iterating pRoomExFirst linked list and comparing each room's sCoords.
void __fastcall GetMinAndMaxCoordinatesFromLevel(D2DrlgLevelStrc * pLevel, int * pOutMinX, int * pOutMinY, int * pOutMaxX, int * pOutMaxY) {
    D2RoomExStrc* pRoomEx = pLevel->pRoomExFirst;
    *pOutMinX = pRoomEx->sCoords.WorldPosition.x;
    *pOutMinY = pRoomEx->sCoords.WorldPosition.y;
    *pOutMaxX = pRoomEx->sCoords.WorldSize.x + pRoomEx->sCoords.WorldPosition.x;
    *pOutMaxY = pRoomEx->sCoords.WorldSize.y + pRoomEx->sCoords.WorldPosition.y;
    for (; pRoomEx; pRoomEx = pRoomEx->pRoomExNext) {
      int nCoord;
      nCoord = pRoomEx->sCoords.WorldSize.x + pRoomEx->sCoords.WorldPosition.x;
      if (nCoord > *pOutMaxX) {
        *pOutMaxX = nCoord;
      }

      nCoord = pRoomEx->sCoords.WorldPosition.x;
      if (nCoord < *pOutMinX) {
        *pOutMinX = nCoord;
      }

      nCoord = pRoomEx->sCoords.WorldSize.y + pRoomEx->sCoords.WorldPosition.y;
      if (nCoord > *pOutMaxY) {
        *pOutMaxY = nCoord;
      }

      nCoord = pRoomEx->sCoords.WorldPosition.y;
      if (nCoord < *pOutMinY) {
        *pOutMinY = nCoord;
      }
    }
}

