    nCellFlags = DrlgGrid::GetGridFlags(pDrlgGridStrc, nX, nRow - 1);
    peD2GridCellFlags[5] = nCellFlags;
    nCellFlags = DrlgGrid::GetGridFlags(pDrlgGridStrc, nX + 1, nRow - 1);
    peD2GridCellFlags[8] = nCellFlags;
    nCellFlags = DrlgGrid::GetGridFlags(pDrlgGridStrc, nX, nRow);
