    nCellFlags = DrlgGrid::GetGridFlags(pDrlgGridStrc, nX + 1, nRow);
    peD2GridCellFlags[7] = nCellFlags;
    nCellFlags = DrlgGrid::GetGridFlags(pDrlgGridStrc, nX, nRowBelow);
